function rootFirstWalk(root: TreeNode | null): number[] {
  const out: number[] = [];
  const visit = (n: TreeNode | null): void => {
    if (!n) return;
    out.push(n.val);
    visit(n.left);
    visit(n.right);
  };
  visit(root);
  return out;
}

